module parity_8bit (
    input [7:0] in,
    output out
);
    parameter [7:0] ENC_OUT = 8'b0;

    assign out = ^{~in[0], in[7:1]};
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire new_n6_, new_n7_, new_n8_, new_n9_, new_n10_;

    assign new_n6_ = (~in[2]) | (~in[3]);
    assign new_n7_ = (sel == 2'b01) ? (~in[1] | ~new_n6_) : new_n6_;
    assign new_n8_ = (sel == 2'b01) ? (~in[0] | ~new_n7_) : new_n7_;
    assign new_n9_ = (~sel) ? 1'b1 : new_n8_;
    assign new_n10_ = (sel == 2'b01) ? (~in[0] | ~new_n9_) : new_n9_;
    assign out = (~new_n6_) | (~new_n10_);
endmodule

module majority (
    input a, b, c,
    output out
);
    assign out = (a & b) | (a & c) | (b & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray = ~binary;
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    assign equal = (a == b);
endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    assign out = {4{ (in != 2'b0) }};
endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(*) begin
    casex (in)
        4'b0001: code = 2'b00;
        4'b001x: code = 2'b01;
        4'b01xx: code = 2'b10;
        4'b1xxx: code = 2'b11;
        default: code = 2'bx;
    endcase
end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    localparam N = 2;
    parameter signed [1:0] INIT = 2'b00;
    parameter signed [1:0] A = 2'b00;
    parameter signed [1:0] B = 2'b00;

    reg signed [1:0] y;
    reg signed [1:0] val_2_reg;
    wire signed [1:0] y_next = clk ? (A + B) : 2'b00;
    wire signed [1:0] val_2_next = reset ? (INIT - {2{y[1]}} ) : 2'b00;

    always @(posedge clk) begin
        y <= reset ? y + y_next : y;
    end

    assign val_2_reg = val_2_next;
    assign state = val_2_reg;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // Define state parameters
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10;

    reg [1:0] current_state;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= S0;
        end else begin
            case (current_state)
                S0: current_state <= S1;
                S1: current_state <= S2;
                S2: current_state <= S0;
                default: current_state <= S0;
            endcase
        end
    end

    // Output logic
    assign light[2] = (current_state == S0) || (current_state == S1);
    assign light[1] = (current_state == S0);
    assign light[0] = (current_state == S0) || (current_state == S2);

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    reg [1:0] val_4_reg;
    wire [1:0] val_5;

    // Combinational logic for val_5 (example: up_request and down_request)
    assign val_5 = up_request & down_request;

    // Registered logic for state (example: capture clk and reset)
    always @(posedge clk or posedge 1'b0) begin
        if (1'b0) begin
            val_4_reg <= 2'b00;
        end else begin
            val_4_reg <= {reset, val_4_reg[1:1]}; // Assuming a typo in the problem's output width
        end
    end

    assign state = val_5 ? val_4_reg : 2'b00;
endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

wire [1:0] a;

// Assign a[1] based on conditions for reset and coin_inserted
always @(*) begin
    if (reset)
        a[1] = coin_inserted;
    else if (coin_inserted)
        a[1] = reset;
    // Else, retain current value (inferred latches)
end

// Assign a[0] based on conditions for clk and item_selected
always @(*) begin
    if (clk)
        a[0] = item_selected;
    else if (item_selected)
        a[0] = clk;
    // Else, retain current value (inferred latches)
end

// Assign output with 2 units time unit
assign #(4) state = a;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);

    // Concatenate the first 4 bits of in_1, in_0, and 4'b0
    assign out = {in_1[3:0], in_0[7:4], 4'b0};

endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

wire [7:0] magnitude = in_0[15] ? (-in_0[14:0] >>> 1) : in_0[14:0];

assign out = (in_0[15]) ? 
                    ( (in_0[14:0] == 15'b0) ? 8'd127 :
                      (in_0[14:0] & (8'h73)) )
                  : 8'd0;

endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    assign out = a + b;
endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);

wire [7:0] concat_val = {a, b};
assign out = {8{~^concat_val}};

endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);
    wire signed [8:0] val1_ext = {{1{b[7]}}, b};
    assign diff = a + val1_ext;
endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);
    // Process a: AND upper 3 bits & lower 5 bits, then sign-extend to 8 bits
    wire [7:0] val_0_and = { {3{ (a[7:3] & a[2:0]) }}, a[7:3] & a[2:0] };
    assign and_out = val_0_and;

    // Process b: XOR upper 3 bits & lower 5 bits, then sign-extend to 8 bits
    wire [7:0] val_1_and = { {3{ (b[7:3] ^ b[2:0]) }}, b[7:3] ^ b[2:0] };
    assign or_out = val_1_and;

    // Process a again for xor_out (same transformation)
    assign xor_out = val_0_and;
endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

assign out = shift[0] ? 8'b00000001 :
               shift[1] ? 8'b00000010 :
               shift[2] ? 8'b00000100 :
               8'b0;

endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);
    assign out = ~in;
endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    wire [7:0] reversed_val0 = {in[0], in[1], in[2], in[3],
                                in[4], in[5], in[6], in[7]};
    wire [7:0] reversed_val1 = {shift[0], shift[1], shift[2]};
    assign out = shift[2] ? reversed_val0 :
                   shift[1] ? 8'hFF :
                   shift[0] ? reversed_val1 : 8'h00;
endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    assign data_out = (~data_in[7]) ? (data_in + 8'd1) : data_in;
endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    assign data_out = data_in - 8'd35;
endmodule

