module ex_top (
    input [7:0] data_in,
    output [7:0] data_out
);
    wire [7:0] N;
    wire [7:0] D;

    // Generate N using combinations of data_in bits with inversion
    assign N[0] = data_in[0] & data_in[1];
    assign N[1] = data_in[2] | data_in[3];
    assign N[2] = ~data_in[4];
    assign N[3] = data_in[5] ^ data_in[6];
    assign N[4] = |data_in[7:4];
    assign N[5] = &data_in[3:0];
    assign N[6] = ~data_in[0];
    assign N[7] = data_in[7] ^ data_in[5];

    // Buffer N to form D
    assign D = {7'b0, N[0]};

    // Invert D for output
    assign data_out = ~D;
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    reg [7:0] shift_reg;

    always @(posedge rst) begin
        if (clk)
            shift_reg <= 8'b00000001;
        else
            shift_reg <= shift_reg << 1;
    end

    assign clk_out = shift_reg[7];
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [4:0] sum = a + b;

    assign gt = sum[0];
    assign eq = sum[1];
    assign lt = sum[4];

endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

    assign out = { {2{enable & in[1]}}, 
                     (enable & ~in[1] & in[0]),
                     (enable & ~in[1] & ~in[0]),
                     (enable & in[1])         };

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);

wire [7:0] dec_out;

assign dec_out = (8'b00000001 << in) & {8{enable}};
assign out = dec_out;

endmodule

