module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);
    reg [1:0] reg0 = 2'b00;
    reg [1:0] reg1 = 2'b00;
    reg [2:0] reg2 = 3'b000;
    reg [1:0] reg3 = 2'b00;

    always @(posedge rst) begin
        if (clk) begin
            reg0 <= reg0 + 1;
        end else begin
            reg0 <= 2'b00;
        end
    end

    always @(posedge rst) begin
        if (clk) begin
            reg1 <= reg1 + 1;
        end else begin
            reg1 <= 2'b00;
        end
    end

    always @(posedge rst) begin
        if (clk) begin
            reg2 <= reg2 + 1;
        end else begin
            reg2 <= 3'b000;
        end
    end

    always @(posedge rst) begin
        if (clk) begin
            reg3 <= reg3 + 1;
        end else begin
            reg3 <= 2'b00;
        end
    end

    assign count = {reg0, reg1, reg2, reg3};
endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg stage0_0, stage0_1;
reg [1:0] stage1_0, stage1_1;
reg [3:0] stage1_2;
reg [3:0] stage2;

// Stage 0: Primary inputs to first two flip-flops
always @(posedge clk) stage0_0 <= 1'b1;
always @(posedge rst) stage0_1 <= 1'b0;

// Stage 1: First two flip-flop outputs
always @(posedge stage0_0) stage1_0 <= 2'h1;
always @(posedge stage0_1) stage1_1 <= 2'h2;

// Stage 2: Combine with AND/OR to 4-bit signal
always @(posedge {stage1_0, stage1_1}) stage1_2 <= {1'b1, stage1_0, stage1_1};

// Stage 3: Final output assignment
always @(posedge stage1_2[3]) stage2 <= 4'b1111;

assign q = stage2;

endmodule

