endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] reg0, reg1;

always @(posedge clk) begin
    reg0 <= 4'b0001 << reg1;
end

always @(posedge rst) begin
    reg1 <= 4'b0001 << reg0;
end

assign q = {reg0, reg1};

endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);

    reg [1:0] stage0, stage1, stage2;
    reg [1:0] next_stage0, next_stage1, next_stage2;

    always @(*) begin
        next_stage0 = {2{clk}};
        next_stage1 = {stage0[0], rst};
        next_stage2 = {stage1[0], sin};
    end

    always @(posedge clk) begin
        stage0 <= next_stage0;
        stage1 <= next_stage1;
        stage2 <= next_stage2;
    end

    assign pout = {next_stage0, next_stage1, next_stage2};

endmodule

module siso_8bit(
