    always @(posedge clk) begin
        stage0 <= 1'b1;
    end

    always @(posedge rst) begin
        stage1 <= stage0;
    end

    always @(posedge sin) begin
        stage2 <= stage1;
    end

    always @(posedge clk) begin
        stage3 <= stage2;
    end

    assign sout = stage3;
endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);

reg [1:0] index;
reg [7:0] seg;

always @(posedge clk) begin
    if (rst) begin
        index <= index + 1;
    end else begin
        index <= 2'b00;
    end
end

always @(*) begin
    case (index)
        2'd0: seg = 8'b01111110;
        2'd1: seg = 8'b00000001;
        2'd2: seg = 8'b01111101;
        2'd3: seg = 8'b01111011;
        2'd4: seg = 8'b01110111;
        2'd5: seg = 8'b01101111;
        2'd6: seg = 8'b00111111;
        2'd7: seg = 8'b00000011;
        default: seg = 8'b00000000;
    endcase
end

assign count = (rst) ? seg : 8'bzzzzzzzz;

endmodule

module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  reg [2:0] selected_value;

  always @(*) begin
    case (clk)
      1'b0: selected_value = {3{resetn}};
