module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  reg [2:0] current_state;
  reg signed [2:0] counter;
  reg state;

  always @(posedge reset) begin
    if (clk) begin
      state <= 1'b0;
      current_state <= 3'b000;
      counter <= 3'sd0;
    end else begin
      case (state)
        1'b0: begin
          if (in) begin
            case (1'b1)
              clk: begin
                current_state <= 3'sd0;
                counter <= 3'sd0;
              end
              in: begin
                current_state <= 3'sd1;
                counter <= 3'sd0;
              end
              reset: begin
                current_state <= 3'sd2;
                counter <= 3'sd0;
              end
              default: begin
                current_state <= current_state;
                counter <= counter;
              end
            endcase
          end
        end
        1'b1: begin
          if (in) begin
            current_state <= 3'sd0;
            counter <= 3'sd0;
          end
        end
      endcase
    end
  end

  assign done = (current_state == 3'sd0) ? 1'b0 :
                 (current_state == 3'sd7) ? 1'b1 :
                 1'bx;

endmodule

