	input rst_n,
	input a,

	output reg rise,
	output reg down
);

    reg [1:0] delay_reg;
    reg [15:0] delay_1;
    reg [15:0] delay_2;

    always @(posedge rst_n or negedge clk) begin
        if (!clk) begin
            delay_reg <= 2'b00;
            delay_1 <= 16'b0;
            delay_2 <= 16'b0;
        end else begin
            delay_reg <= {delay_reg[0], delay_reg[1]};
            delay_1 <= {16{delay_reg[1]}};
            delay_2 <= {16{delay_reg[1]}};
        end
    end

    always @(posedge a or negedge clk) begin
        if (!clk) begin
            rise <= 1'b0;
            down <= 1'b0;
