module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [2:0] counter;
    reg [2:0] next_counter;

    // Counter logic
    always @(posedge rst_n or negedge clk) begin
        if (~clk) begin
            counter <= 3'b0;
        end else begin
            counter <= next_counter;
        end
    end

    // Next counter value logic
    always @(*) begin
        if (~clk) begin
            next_counter = 3'b0;
        end else begin
            if (counter == NUM_DIV - 1) begin
                next_counter = 3'd0;
            end else begin
                next_counter = counter + 1;
            end
        end
    end

    // Output logic
    assign clk_div = (counter == NUM_DIV - 1) && rst_n;

endmodule

