module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  reg [3:0] next_val;

  always @(*) begin
    next_val = {4{rst}}; // Initialize all bits to rst
    next_val[0] = rst | clk;
    next_val[1] = rst ^ clk;
    next_val[2] = ~rst;
    next_val[3] = next_val[2]; // Dependency on next_val[2]
  end

  always @(posedge clk) begin
    out <= next_val;
  end

endmodule

module right_shifter(clk, q,d);  

    input  clk;  
    input d;  
    output  [7:0] q;  

    reg [7:0] stage1, stage2, stage3;  

    // First stage: Capture d and clk with 2 time units delay  
    always @(d, clk) begin  
        stage1 <= #2 {d, 7'b0, clk};  
    end  

    // Second stage: Capture previous stage's output with 2 time units delay  
    always @(stage1) begin  
        stage2 <= #2 {stage1[7], 7'b0, stage1[0]};  
    end  

    // Third stage: Capture previous stage's output with 2 time units delay  
    always @(stage2) begin  
        stage3 <= #2 {stage2[7], 7'b0, stage2[0]};  
    end  

    // Fourth stage: Capture previous stage's output with 2 time units delay  
    always @(stage3) begin  
        q <= #2 {stage3[7], 7'b0, stage3[0]};  
    end  

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

reg [3:0] int_reg;
reg [3:0] temp;

integer i;
reg [3:0] next_int;

always @(*) begin
	next_int = int_reg;
	for (i = 0; i < 4; i = i + 1) begin
		if (data_en) begin
			// Priority to data_en: update bit i with arstn
			next_int[i] = arstn;
		] else begin
			// Check brstn, then data_in, then default
			if (brstn) begin
				next_int[i] = brstn;
		 end else if (data_in[i]) begin
			 next_int[i] = data_in[i];
		 end else begin
			 next_int[i] = arstn;
		 end
	 end
 end
endfunction

always @(posedge clk_a or negedge clk_b) begin
	if (!clk_b) begin
		int_reg <= 4'b0;
		temp <= 4'b0;
		dataout <= 4'b0;
 end] else begin
		int_reg <= next_int;
		temp <= next_int;
		dataout <= next_int;
 end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

reg [2:0] counter;
reg [1:0] current_state, next_state;

parameter s0 = 2'b00,
          s1 = 2'b01,
          s2 = 2'b10,
          s3 = 2'b11;

// State transition and counter logic
always @(posedge RST, posedge IN) begin
  if (IN) begin
    current_state <= s0;
    counter <= 0;
  end else begin
    current_state <= next_state;
    if (current_state != s0)
      counter <= counter + 1;
    else
      counter <= 0;
  end
end

// Next state logic
always @(*) begin
  case (current_state)
    s0: next_state = CLK ? s1 : s0;
    s1: next_state = s2;
    s2: next_state = s3;
    s3: next_state = CLK ? s1 : s3;
    default: next_state = s0;
  endcase
end

// Output logic
always @(*) begin
  MATCH = (current_state == s1) || (current_state == s3 && !CLK);
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [3:0] internal_reg;
    reg [3:0] val_3_reg;
    reg [3:0] val_4_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            internal_reg <= 4'b0;
        else
            internal_reg <= d;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            val_3_reg <= 4'b0;
        else
            val_3_reg <= {internal_reg[internal_reg[3:1]]}, internal_reg[0];
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            val_4_reg <= 4'b0;
        else
            val_4_reg <= {d[internal_reg[3:1]], internal_reg[0]};
    end

    assign #1 valid_out = val_3_reg;
    assign #1 dout = val_4_reg;

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
     parameter [23:0] PAR_A = 24'h0;
     parameter [23:0] PAR_B = 24'h0;
     parameter [15:0] SINK_TILTE = "TILTE";

     reg [23:0] par_a;
     reg [23:0] par_b;
     reg [23:0] par_a_next, par_b_next;

     integer i;
     reg [15:0] sink_title_reg;

     always @(*) begin
         // Default next values
         par_a_next = par_a;
         par_b_next = par_b;
         sink_title_reg = SINK_TILTE;

         // Process each bit from PAR_A
         for (i = 0; i < 24; i = i + 1) begin
             if (par_a[i]) begin
                 par_a_next = PAR_A;
                 par_b_next = PAR_B;
             end
         end

         // Process each bit from PAR_B
         for (i = 0; i < 24; i = i + 1) begin
             if (par_b_next[i]) begin
                 par_a_next = PAR_A;
                 par_b_next = PAR_B;
             end
         end

         // Update flip-flops
         par_a <= par_a_next;
         par_b <= par_b_next;
         sink_title_reg <= sink_title_reg;
     end

     assign sequence_detected = sink_title_reg;

     // Initialize flip-flops
     initial begin
         par_a = 24'h0;
         par_b = 24'h0;
         sink_title_reg = SINK_TILTE;
     end
     // Note: The above initialization may not work in certain Verilog versions.
     // The problem's specifications are incompatible, so a placeholder is used.
     // Below code is not recommended for synthesis as a black box
     // due to potential IO buffer insertion issues.

     /* synthesis syn_black_box black_box_pad_pin="clk, rst_n, data_in, sequence_detected" */
     /* synthesis syn_noprune =1 */
endmodule
